// Send push notification to a specific user
async function sendPushToUser(userId, payload) {
    // Both keys required: setVapidDetails is skipped when either is missing, and sending
    // without a VAPID identity fails per-subscription with errors the catch below swallows.
    if (!process.env.VAPID_PUBLIC_KEY || !process.env.VAPID_PRIVATE_KEY) return; // Push not configured
    try {
        const subs = query.all('SELECT * FROM push_subscriptions WHERE user_id = ?', [userId]);
        const message = JSON.stringify(payload);
        for (const sub of subs) {
            try {
                await webpush.sendNotification({
                    endpoint: sub.endpoint,
                    keys: { p256dh: sub.p256dh, auth: sub.auth }
                }, message);
            } catch (err) {
                if (err.statusCode === 410 || err.statusCode === 404) {
                    // Subscription expired/invalid — remove it
                    db.run('DELETE FROM push_subscriptions WHERE id = ?', [sub.id]);
                    saveDb();
                }
            }
        }
    } catch (err) {
        console.error('Push notification error:', err);
    }
}

// Broadcast a push to every subscribed device. Used to drain the shared push_outbox that the
// admin portal writes to (admin has no VAPID/web-push, so the user portal does the sending).
async function sendPushToAll(payload) {
    if (!process.env.VAPID_PUBLIC_KEY || !process.env.VAPID_PRIVATE_KEY) return 0;
    let sent = 0;
    try {
        const subs = query.all('SELECT * FROM push_subscriptions');
        const message = JSON.stringify(payload);
        for (const sub of subs) {
            try {
                await webpush.sendNotification({ endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } }, message);
                sent++;
            } catch (err) {
                if (err.statusCode === 410 || err.statusCode === 404) { db.run('DELETE FROM push_subscriptions WHERE id = ?', [sub.id]); saveDb(); }
            }
        }
    } catch (err) { console.error('Push broadcast error:', err.message); }
    return sent;
}

// Drain the shared push_outbox: admin enqueues announcements here; we send + mark sent.
let _outboxBusy = false;
async function drainPushOutbox() {
    if (_outboxBusy || !process.env.VAPID_PUBLIC_KEY || !process.env.VAPID_PRIVATE_KEY) return;
    _outboxBusy = true;
    try {
        let rows = [];
        try { rows = query.all("SELECT * FROM push_outbox WHERE COALESCE(sent,0) = 0 ORDER BY created_at ASC LIMIT 20"); } catch (e) { return; }
        for (const r of rows) {
            const payload = { title: r.title || 'Med&X', body: r.body || '', url: r.url || '/?app=1' };
            let n = 0;
            if (r.target_email) {
                // Targeted: resolve the user by email, push only their devices.
                const u = query.get('SELECT id FROM users WHERE LOWER(email) = LOWER(?)', [r.target_email]);
                if (u) { await sendPushToUser(u.id, payload); n = 1; }
                console.log(`[Push] Direct "${r.title}" → ${r.target_email}${u ? '' : ' (no such user)'}.`);
            } else {
                n = await sendPushToAll(payload);
                console.log(`[Push] Broadcast "${r.title}" to ${n} device(s).`);
            }
            db.run("UPDATE push_outbox SET sent = 1, sent_at = ?, sent_count = ? WHERE id = ?", [new Date().toISOString(), n, r.id]);
            saveDb();
        }
    } catch (e) { console.error('[Push] outbox drain failed:', e.message); }
    finally { _outboxBusy = false; }
}

// Project -> its registration table. The one common join key across every project's registration
// table is the email column, so audience membership is resolved by email (notify_topics carries
// user_id -> users.email; each reg table carries email). Whitelisted table names, read-only.
const AUDIENCE_REG_TABLE = { plexus: 'registrations', gala: 'gala_registrations', accelerator: 'accelerator_applications', forum: 'forum_event_registrations', bridges: 'bridges_registrations' };

// Distinct lower-cased registrant emails for a project (empty on any error / unknown project).
function registrantEmailsForProject(project) {
    const table = AUDIENCE_REG_TABLE[project];
    if (!table) return [];
    try {
        return query.all(`SELECT DISTINCT LOWER(TRIM(email)) AS email FROM ${table} WHERE email IS NOT NULL AND TRIM(email) <> ''`).map(r => r.email);
    } catch (e) { return []; }
}

// Which project keys a member (by email) has registered for, across all reg tables. Used by the
// announcement feed filter for 'registered' / 'interested_not_registered' scoped items.
function memberRegisteredProjects(email) {
    if (!email) return [];
    const e = String(email).trim().toLowerCase();
    if (!e) return [];
    const out = [];
    for (const k in AUDIENCE_REG_TABLE) {
        try { if (query.get(`SELECT 1 FROM ${AUDIENCE_REG_TABLE[k]} WHERE LOWER(TRIM(email)) = ? LIMIT 1`, [e])) out.push(k); } catch (e2) {}
    }
    return out;
}

// Fan a push=1 member announcement out to the shared push_outbox: one row per member in the
// announcement's chosen audience (see audience_scope), or every user for a global item.
// This ENQUEUES only — the actual web-push send happens later in drainPushOutbox, which no-ops
// unless VAPID is configured. So in dev the rows land in the outbox but nothing ever fires.
// push_fanned flips to 1 so a given announcement is never fanned twice (idempotent).
let _annFanBusy = false;
function fanoutAnnouncements() {
    if (_annFanBusy) return;
    _annFanBusy = true;
    try {
        let anns = [];
        try { anns = query.all('SELECT * FROM member_announcements WHERE COALESCE(push,0) = 1 AND COALESCE(push_fanned,0) = 0'); }
        catch (e) { return; }
        for (const a of anns) {
            let emails = [];
            const scope = a.audience_scope || 'everyone';
            if (!a.project_key || scope === 'everyone') {
                emails = query.all('SELECT DISTINCT email FROM users WHERE email IS NOT NULL').map(r => r.email);
            } else {
                const subscribers = query.all(
                    `SELECT DISTINCT LOWER(TRIM(u.email)) AS email FROM notify_topics nt
                       JOIN users u ON u.id = nt.user_id
                      WHERE nt.project_key = ? AND u.email IS NOT NULL AND TRIM(u.email) <> ''`, [a.project_key]
                ).map(r => r.email);
                if (scope === 'registered') {
                    emails = registrantEmailsForProject(a.project_key);
                } else if (scope === 'interested_not_registered') {
                    const reg = new Set(registrantEmailsForProject(a.project_key));
                    emails = subscribers.filter(em => !reg.has(em));
                } else {
                    // 'interested' — the default for a project-scoped item
                    emails = subscribers;
                }
            }
            const url = a.link_section ? ('/?app=1&section=' + a.link_section) : '/?app=1';
            for (const em of emails) {
                db.run('INSERT INTO push_outbox (id, title, body, url, target_email, created_by) VALUES (?,?,?,?,?,?)',
                    [uuidv4(), a.title, String(a.body || '').slice(0, 140), url, em, 'announcement:' + a.id]);
            }
            db.run('UPDATE member_announcements SET push_fanned = 1 WHERE id = ?', [a.id]);
            saveDb();
            console.log(`[Announce] Fanned "${a.title}" to ${emails.length} subscriber(s) of ${a.project_key || 'ALL'} (enqueued to outbox).`);
        }
    } catch (e) { console.error('[Announce] fanout failed:', e.message); }
    finally { _annFanBusy = false; }
}

