// Format an ISO date (YYYY-MM-DD) as "5 December 2026" for emails; falls back to the raw value.
function fmtEventDate(d) {
    if (!d) return '';
    try { const dt = new Date(String(d) + 'T00:00:00Z'); if (isNaN(dt.getTime())) return String(d); return dt.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }); } catch(e) { return String(d); }
}
// Best-effort "date · time · venue" line for an event, read live from the DB (correct per event).
function lookupEventWhen(eventType, regId) {
    try {
        if (eventType === 'gala')   { const g = query.get("SELECT date, time, venue FROM gala_settings WHERE id='default'"); return g ? [fmtEventDate(g.date), g.time, g.venue].filter(Boolean).join(' · ') : ''; }
        if (eventType === 'plexus') { const c = getActiveConference(); return c ? [fmtEventDate(c.start_date), c.venue_name, c.venue_city].filter(Boolean).join(' · ') : ''; }
        if (eventType === 'bridges'){ const r = query.get('SELECT event_id FROM bridges_registrations WHERE id = ?', [regId]); if (r && r.event_id) { const b = query.get('SELECT event_date, event_time, venue_name, city FROM bridges_events WHERE id = ?', [r.event_id]); if (b) return [fmtEventDate(b.event_date), b.event_time, b.venue_name, b.city].filter(Boolean).join(' · '); } return ''; }
        if (eventType === 'forum')  { const f = query.get("SELECT date, venue FROM forum_gala_settings WHERE id='default'"); return f ? [fmtEventDate(f.date), f.venue].filter(Boolean).join(' · ') : ''; }
    } catch(e) {}
    return '';
}

// ---- Hosted ticket-QR helpers ----
// Confirmation emails reference GET /qr/<registrationId>.png instead of an inline data: URI,
// because Gmail and Outlook strip data: URIs (guests saw a broken image instead of their ticket).
// The same PNG is also attached to the email so the ticket survives image-blocking clients.
const QR_BASE_URL = process.env.RENDER_EXTERNAL_URL || 'https://medx-user-portal.onrender.com';
function qrImageUrl(regId) { return `${QR_BASE_URL}/qr/${regId}.png`; }

// Bank-transfer details for invoices. Returns null (→ "contact us for payment details")
// unless a REAL IBAN is configured. The old code fell back to a placeholder IBAN
// (HR1234567890123456789, also pinned in render.yaml), so a real payer could wire money
// to a non-existent account. A valid Croatian IBAN is 21 chars and the placeholder is
// explicitly rejected.
const PLACEHOLDER_IBANS = new Set(['HR1234567890123456789', 'HR12345678901', '']);
function getBankDetails(reference, amount) {
    const iban = (process.env.MEDX_IBAN || '').replace(/\s+/g, '');
    if (!iban || PLACEHOLDER_IBANS.has(iban) || !/^[A-Z]{2}[0-9A-Z]{13,32}$/.test(iban)) {
        return null; // not configured / still a placeholder — do not show a fake account
    }
    return {
        iban,
        bank_name: process.env.MEDX_BANK_NAME || 'Zagrebačka banka d.d.',
        swift: process.env.MEDX_SWIFT || '',
        recipient: process.env.MEDX_COMPANY_NAME || 'Med&X',
        reference,
        amount,
        currency: 'EUR'
    };
}

async function qrPngAttachment(payload) {
    try {
        // Encode only the minimal token (id + event) so the attached ticket QR is sparse + easy to
        // scan; the scanner reads name/status/guests from the DB by regId.
        const slim = (payload && payload.regId) ? { type: 'MEDX_MEMBER', regId: payload.regId, evt: payload.evt } : payload;
        const png = await QRCode.toBuffer(JSON.stringify(slim), { errorCorrectionLevel: 'L', width: 560, margin: 2, color: { dark: '#000000', light: '#ffffff' } });
        return [{ filename: 'plexus-ticket-qr.png', content: png, type: 'image/png' }];
    } catch (e) {
        console.warn('QR attachment generation failed:', e.message);
        return [];
    }
}

// Ticket-style QR card used by every confirmation email (email-client-safe tables only)
// Inbox preview line (the grey text after the subject in Gmail/Outlook). Hidden in the body.
function emailPreheader(text) {
    if (!text) return '';
    return `<div style="display:none;max-height:0px;overflow:hidden;mso-hide:all;">${escapeHtml(text)}${'&nbsp;&zwnj;'.repeat(30)}</div>`;
}

function buildTicketQrBlock(regId, opts = {}) {
    const label = opts.label || 'Your Check-in QR Code';
    const caption = opts.caption || 'Present this code at the event entrance';
    const attachNote = opts.attachNote || 'Your QR is also attached to this email — save it to your phone.';
    return `
    <table width="100%" cellpadding="0" cellspacing="0" style="margin:26px 0;"><tr><td align="center">
        <table cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e6dfc8;border-radius:18px;overflow:hidden;box-shadow:0 3px 14px rgba(15,23,42,0.07);">
            <tr><td style="background:linear-gradient(90deg,#b8922e,#C9A962,#dfc070,#C9A962,#b8922e);height:4px;font-size:0;line-height:0;">&nbsp;</td></tr>
            <tr><td style="padding:22px 34px 6px;text-align:center;font-size:11px;font-weight:700;color:#C9A962;text-transform:uppercase;letter-spacing:2.5px;">${label}</td></tr>
            <tr><td align="center" style="padding:10px 34px 6px;text-align:center;">
                <img src="${qrImageUrl(regId)}" alt="Check-in QR code" width="220" height="220" style="display:block;margin:0 auto;border:0;" />
            </td></tr>
            <tr><td style="padding:0 34px 4px;text-align:center;font-size:12px;color:#94a3b8;letter-spacing:2px;font-family:'Courier New',monospace;"><span style="font-family:Arial,Helvetica,sans-serif;letter-spacing:1.5px;color:#b0b8c4;font-size:9px;">MANUAL CODE&nbsp;&nbsp;</span>${String(regId).substring(0, 8).toUpperCase()}</td></tr>
            <tr><td style="padding:6px 34px 22px;text-align:center;font-size:12px;color:#64748b;line-height:1.6;">${caption}<br><span style="color:#94a3b8;">${attachNote}</span></td></tr>
        </table>
    </td></tr></table>`;
}

// Safety net: a single bad request must NOT take down the whole service (critical on event day).
// Node 15+ exits the process on an unhandled promise rejection — e.g. an async route that throws
// after its try/catch. Log it instead of crashing so Render keeps serving everyone else.
process.on('unhandledRejection', (reason) => { console.error('[unhandledRejection]', (reason && reason.stack) || reason); });

const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET || (process.env.NODE_ENV === 'development' ? 'medx-dev-secret' : (() => { console.error('FATAL: JWT_SECRET environment variable is required in production'); process.exit(1); })());

