// Revoked invite IDs — links whose `i` value appears here are permanently disabled,
// regardless of their embedded expiry date. To revoke a link, add its UUID and redeploy.
const REVOKED_INVITE_IDS = new Set([
    '9799cb97-e3a7-493a-ac23-ee2910e8457b', // Annual Biomedical Forum 2026 / Gala Evening — revoked 2026-05-19
]);

// Serves a full server-rendered HTML page for VIP invite links.
// Must be defined BEFORE express.static so it takes priority over the SPA.
// ========== PLEXUS EXPERIENCE — public 3-event chooser (Conference / Bridges / Gala) ==========
// One page, registrant picks which events to attend. Posts to the source-aware
// /api/croatians-abroad/register with source='plexus' so the Gala portion lands in the SAME
// gala_registrations table + Gala Sheet tab as every other Gala entry point (unified data).
// Reachable publicly at /plexus and via an admin-generated link at /plexus/:token (the token's
// registration_links.component_keys decide which of the three events the link OFFERS).
const PLEXUS_SHELL = (inner, title) => `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>${title || 'Plexus 2026'}</title><link rel="icon" type="image/png" href="/assets/favicon-x.png"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>
    * { margin:0; padding:0; box-sizing:border-box; }
    body { min-height:100vh; background:linear-gradient(160deg,#0f172a,#1e293b); font-family:-apple-system,BlinkMacSystemFont,'Inter',system-ui,sans-serif; color:#e2e8f0; padding:32px 16px; }
    /* Wide on desktop (was a fixed 640px strip — that's why it didn't use desktop space). */
    .container { max-width:1080px; margin:0 auto; }
    @media (min-width:1280px) { .container { max-width:1200px; } }
    .logo { text-align:center; margin-bottom:24px; }
    .logo img { height:38px; width:auto; display:inline-block; filter:brightness(0) invert(1); }
    .logo span { font-size:28px; font-weight:700; color:#fff; letter-spacing:-0.5px; }
    .logo span em { font-style:normal; color:#c9a962; }
    .card { background:rgba(255,255,255,0.03); border:1px solid rgba(201,169,98,0.2); border-radius:20px; padding:28px 26px; min-width:0; max-width:100%; }
    /* Hero header band spanning the full width on desktop. */
    .hero { background:linear-gradient(135deg,rgba(201,169,98,0.12),rgba(201,169,98,0.02)); border:1px solid rgba(201,169,98,0.22); border-radius:20px; padding:34px 28px; text-align:center; margin-bottom:20px; }
    .hero .lede { max-width:640px; margin:0 auto; }
    /* Two-column layout on desktop: events on the left, the form on the right. */
    .plex-layout { display:grid; grid-template-columns:minmax(0,1.25fr) minmax(0,1fr); gap:20px; align-items:start; }
    .form-col { position:sticky; top:24px; }
    .badge { display:inline-block; font-size:10px; font-weight:700; letter-spacing:2px; text-transform:uppercase; color:#c9a962; margin-bottom:12px; padding:5px 12px; background:rgba(201,169,98,0.12); border-radius:20px; }
    h1 { font-size:24px; font-weight:700; color:#fff; margin-bottom:6px; line-height:1.2; }
    .hero h1 { font-size:clamp(26px,4vw,38px); }
    .lede { font-size:14px; color:#94a3b8; margin-bottom:8px; line-height:1.55; }
    .section-label { font-size:11px; font-weight:700; letter-spacing:1.5px; text-transform:uppercase; color:#c9a962; margin:22px 0 12px; }
    .plex-cal-row { margin-top:16px; padding-top:16px; border-top:1px solid rgba(201,169,98,0.18); display:flex; flex-wrap:wrap; align-items:center; gap:10px; }
    .plex-cal-label { font-size:11px; font-weight:700; letter-spacing:1.5px; text-transform:uppercase; color:#94a3b8; }
    .plex-cal-links { display:flex; flex-wrap:wrap; gap:8px; }
    .plex-cal-btn { display:inline-flex; align-items:center; gap:6px; padding:8px 14px; border:1px solid rgba(201,169,98,0.4); border-radius:999px; background:rgba(201,169,98,0.08); color:#e8e2d4; font-size:12.5px; font-weight:600; text-decoration:none; transition:all 0.2s; }
    .plex-cal-btn:hover { background:rgba(201,169,98,0.18); transform:translateY(-1px); }
    .plex-cal-btn i { color:#c9a962; font-size:12px; }
    .event-option { background:rgba(255,255,255,0.04); border:1.5px solid rgba(255,255,255,0.08); border-radius:12px; padding:16px; margin-bottom:10px; display:flex; gap:14px; cursor:pointer; transition:all 0.2s; position:relative; overflow:hidden; }
    .event-option::before { content:''; position:absolute; left:0; top:0; bottom:0; width:3px; background:transparent; transition:background 0.2s; }
    .event-option:hover { border-color:rgba(201,169,98,0.3); background:rgba(255,255,255,0.06); transform:translateY(-1px); }
    .event-option.evt-conference::before { background:rgba(167,139,250,0.5); }
    .event-option.evt-bridges::before { background:rgba(45,212,191,0.5); }
    .event-option.evt-gala::before { background:rgba(201,169,98,0.5); }
    .event-option.evt-conference.selected { border-color:#a78bfa; background:rgba(167,139,250,0.06); }
    .event-option.evt-conference.selected::before { background:#a78bfa; width:4px; }
    .event-option.evt-bridges.selected { border-color:#2dd4bf; background:rgba(45,212,191,0.06); }
    .event-option.evt-bridges.selected::before { background:#2dd4bf; width:4px; }
    .event-option.evt-gala.selected { border-color:#c9a962; background:rgba(201,169,98,0.08); }
    .event-option.evt-gala.selected::before { background:#c9a962; width:4px; }
    .event-checkbox { flex-shrink:0; width:22px; height:22px; border:2px solid rgba(255,255,255,0.2); border-radius:6px; display:flex; align-items:center; justify-content:center; margin-top:2px; transition:all 0.2s; }
    .event-option.evt-conference.selected .event-checkbox { background:#a78bfa; border-color:#a78bfa; }
    .event-option.evt-bridges.selected .event-checkbox { background:#2dd4bf; border-color:#2dd4bf; }
    .event-option.evt-gala.selected .event-checkbox { background:#c9a962; border-color:#c9a962; }
    .event-checkbox i { color:#fff; font-size:12px; display:none; }
    .event-option.selected .event-checkbox i { display:block; }
    .event-icon { flex-shrink:0; width:44px; height:44px; border-radius:13px; display:flex; align-items:center; justify-content:center; font-size:18px; margin-top:-1px; box-shadow:0 5px 16px rgba(0,0,0,0.24); transition:transform 0.2s ease; }
    .event-option:hover .event-icon { transform:scale(1.06); }
    .event-option.evt-conference .event-icon { background:linear-gradient(135deg,rgba(167,139,250,0.32),rgba(167,139,250,0.07)); color:#c4b5fd; border:1px solid rgba(167,139,250,0.28); }
    .event-option.evt-bridges .event-icon { background:linear-gradient(135deg,rgba(45,212,191,0.32),rgba(45,212,191,0.07)); color:#5eead4; border:1px solid rgba(45,212,191,0.28); }
    .event-option.evt-gala .event-icon { background:linear-gradient(135deg,rgba(201,169,98,0.34),rgba(201,169,98,0.08)); color:#e8c97a; border:1px solid rgba(201,169,98,0.30); }
    .event-body { flex:1; }
    .event-title-row { display:flex; justify-content:space-between; gap:10px; align-items:baseline; margin-bottom:4px; }
    .event-name { font-size:15.5px; font-weight:600; color:#fff; }
    .event-price { font-size:13px; font-weight:600; color:#c9a962; white-space:nowrap; }
    .event-price.free { color:#22c55e; }
    .event-meta { font-size:12px; color:#94a3b8; line-height:1.45; }
    .event-status { display:inline-block; font-size:10px; font-weight:700; letter-spacing:0.6px; text-indent:0.6px; text-align:center; text-transform:uppercase; color:#c9a962; background:rgba(201,169,98,0.12); border:1px solid rgba(201,169,98,0.25); padding:2px 9px; border-radius:20px; margin:2px 0 6px; }
    .event-date { font-size:12.5px; font-weight:600; color:#e2e8f0; margin-bottom:4px; }
    /* Gala keynote highlight (Lord Smith of Finsbury, Chancellor of Cambridge). */
    .keynote-card { background:linear-gradient(135deg,rgba(201,169,98,0.12),rgba(201,169,98,0.02)); border:1px solid rgba(201,169,98,0.28); border-radius:14px; padding:16px 18px; margin-top:14px; display:flex; gap:16px; align-items:center; }
    .keynote-card img { width:72px; height:72px; border-radius:50%; object-fit:cover; object-position:center 22%; border:2px solid #c9a962; flex-shrink:0; box-shadow:0 4px 14px rgba(0,0,0,0.25); }
    .keynote-card .kc-label { font-size:9px; letter-spacing:2.5px; text-transform:uppercase; color:#c9a962; font-weight:700; margin-bottom:4px; }
    .keynote-card .kc-name { font-size:15.5px; font-weight:600; color:#fff; line-height:1.2; }
    .keynote-card .kc-role { font-size:12.5px; font-style:italic; color:#e8c97a; margin-top:3px; }
    .form-grid { display:grid; gap:14px; margin-top:6px; }
    .form-row { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
    label { display:block; font-size:11px; font-weight:600; color:#94a3b8; margin-bottom:5px; }
    input, select, textarea { width:100%; padding:11px 13px; border:1px solid rgba(255,255,255,0.1); border-radius:9px; background:rgba(255,255,255,0.05); color:#fff; font-size:13.5px; font-family:inherit; }
    input:focus, select:focus, textarea:focus { border-color:#c9a962; outline:none; box-shadow:0 0 0 3px rgba(201,169,98,0.1); }
    input::placeholder, textarea::placeholder { color:#64748b; }
    textarea { resize:vertical; min-height:60px; }
    .total-display { display:none; justify-content:space-between; align-items:center; padding:14px 16px; background:rgba(201,169,98,0.1); border-radius:10px; border:1px solid rgba(201,169,98,0.25); margin-top:16px; }
    .total-display.show { display:flex; }
    .total-display .label { font-size:13px; color:#94a3b8; }
    .total-display .amount { font-size:22px; font-weight:700; color:#c9a962; }
    .submit-btn { width:100%; margin-top:16px; padding:15px; border:none; border-radius:11px; background:linear-gradient(135deg,#c9a962,#b8965a); color:#0f172a; font-size:15px; font-weight:700; cursor:pointer; transition:all 0.2s; }
    .submit-btn:hover { transform:translateY(-1px); box-shadow:0 8px 20px rgba(201,169,98,0.25); }
    .submit-btn:disabled { opacity:0.55; cursor:not-allowed; transform:none; box-shadow:none; }
    .msg { margin-top:14px; padding:12px 14px; border-radius:9px; font-size:13px; display:none; }
    .msg.err { display:block; background:rgba(239,68,68,0.12); border:1px solid rgba(239,68,68,0.3); color:#fca5a5; }
    .foot { text-align:center; font-size:12px; color:#64748b; margin-top:20px; }
    .foot a { color:#c9a962; text-decoration:none; }
    /* Mid widths — drop the two-column split to a single stacked column. */
    @media (max-width: 880px) {
        .plex-layout { grid-template-columns: minmax(0, 1fr); }
        .form-col { position: static; }
    }
    /* Tablet / large phone — stack the form to one column, tighten the cards (mirrors the Gala
       page's 768px breakpoint so the layout adapts the same way). */
    @media (max-width: 768px) {
        body { padding: 22px 12px; }
        .container { max-width: 100%; }
        .card { padding: 22px 18px; }
        .logo span { font-size: 24px; }
        h1 { font-size: 21px; }
        .lede { font-size: 13.5px; }
        .event-option { padding: 14px; gap: 12px; }
        .event-icon { width: 34px; height: 34px; font-size: 14px; }
        .event-name { font-size: 14.5px; }
        .event-price { font-size: 12.5px; white-space: normal; }
        .event-meta { font-size: 11.5px; }
        .form-row { grid-template-columns: 1fr; gap: 12px; }
        .submit-btn { padding: 14px; font-size: 14px; }
        /* iOS Safari auto-zooms any focused control whose font-size is < 16px.
           Bump form controls to 16px on phones/tablets only (desktop keeps 13.5px). */
        input, select, textarea { font-size: 16px; }
        /* Comfortable 44px touch targets for the add-to-calendar chips. */
        .plex-cal-btn { min-height: 44px; }
    }
    /* Small phone — further compaction, larger touch targets kept comfortable. */
    @media (max-width: 480px) {
        body { padding: 16px 10px; }
        .card { padding: 18px 14px; border-radius: 16px; }
        h1 { font-size: 19px; margin-bottom: 8px; }
        .lede { font-size: 12.5px; line-height: 1.55; }
        .event-title-row { flex-wrap: wrap; gap: 4px; }
        .event-name { font-size: 14px; }
        .section-label { font-size: 10px; margin: 18px 0 10px; }
        .total-display .amount { font-size: 19px; }
        .foot { font-size: 11px; }
    }
</style></head><body><div class="container">
    <div class="logo"><img src="${MEDX_LOGO_URL}" alt="Med&amp;X" /></div>
    ${inner}
    <div class="foot">Questions? <a href="mailto:laura.rodman@medx.hr">laura.rodman@medx.hr</a> &middot; <a href="https://medx.hr">medx.hr</a><br>
        <span style="display:inline-block;margin-top:8px;">
            <a href="https://www.linkedin.com/company/med-x-association/">LinkedIn</a> &middot;
            <a href="https://www.instagram.com/medx_association/">Instagram</a> &middot;
            <a href="https://www.facebook.com/profile.php?id=61554188818525">Facebook</a>
        </span>
    </div>
</div></body></html>`;

const plexusNoticePage = (heading, body) => PLEXUS_SHELL(`<div class="card" style="text-align:center;"><h1 style="color:#ef4444;">${heading}</h1><p class="lede" style="margin-top:10px;">${body}</p></div>`, heading);

app.get(['/plexus', '/plexus/:token'], async (req, res) => {
    try {
        await freshSync();
        const token = (req.params.token || req.query.t || '').toString().trim();
        let link = null, linkLabel = '';
        let offered = ['conference', 'bridges', 'gala'];
        if (token) {
            try { link = query.get("SELECT * FROM registration_links WHERE token = ? AND event_type = 'plexus'", [token]); } catch(e) { link = null; }
            if (link) {
                if (link.is_active === 0) return res.send(plexusNoticePage('Link Disabled', 'This registration link is no longer active. Please contact the Med&amp;X team.'));
                if (link.expires_at && new Date(link.expires_at) < new Date()) return res.send(plexusNoticePage('Link Expired', 'This registration link has expired.'));
                if (link.max_uses && Number(link.max_uses) > 0 && Number(link.uses || 0) >= Number(link.max_uses)) return res.send(plexusNoticePage('Link Fully Used', 'This registration link has reached its maximum number of uses.'));
                try { const a = JSON.parse(link.component_keys || 'null'); if (Array.isArray(a) && a.length) offered = a.filter(k => ['conference', 'bridges', 'gala'].includes(k)); } catch(e) {}
                linkLabel = link.label || '';
            }
        }
        if (!offered.length) offered = ['conference', 'bridges', 'gala'];

        const galaSettings = query.get("SELECT * FROM gala_settings WHERE id = 'default'") || {};
        const galaPrice = effectiveGalaPrice();
        const ebDeadline = galaSettings.early_bird_deadline || '2026-09-01';
        const isEarly = new Date().toISOString().slice(0, 10) <= ebDeadline;
        const fmtD = (iso) => { try { return new Date(iso).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }); } catch(e) { return iso; } };
        const galaVenue = galaSettings.venue || 'Hotel Esplanade Zagreb';
        const galaPriceLabel = isEarly ? ('&euro;' + galaPrice + ' &middot; early-bird until ' + fmtD(ebDeadline)) : ('&euro;' + galaPrice);

        // "Vec imate racun?" member-card toggle for this fixed page (admin -> Sign-up Forms ->
        // fixed-page toggles; rewards_settings key member_card_page-plexus, absent = ON). OFF hides
        // the signed-in note + prefill only — PLEX_AUTH (account linking on submit) is unchanged.
        const showMemberCard = rewardsSetting('member_card_page-plexus', '1') !== '0';

        // Admin-editable copy (lede + per-event descriptions) from plexus_page_settings, with the
        // launch defaults as fallback. {venue} in the Gala description resolves to the live venue.
        const pps = query.get("SELECT * FROM plexus_page_settings WHERE id = 'default'") || {};
        const pageLede = pps.page_lede || 'Register once, from this single page. Choose the events you would like to attend — the Conference and Croatian Biomedical Bridges are complimentary; the Gala Evening is a paid ticket.';
        const confTitle = pps.conference_title || 'Plexus Conference';
        const confStatus = pps.conference_status || '';
        const confDate = pps.conference_date || '';
        const confDesc = pps.conference_desc || '4–5 December 2026 · Zagreb · two days of panels & lectures across biomedicine. Program to follow · limited spaces.';
        const bridgesTitle = pps.bridges_title || 'Croatian Biomedical Bridges';
        const bridgesStatus = pps.bridges_status || '';
        const bridgesDate = pps.bridges_date || '';
        const bridgesDesc = pps.bridges_desc || '4 or 5 December 2026 · Zagreb · a daytime gathering connecting Croatian medicine worldwide. Pre-registration; date & venue to follow.';
        const galaTitle = pps.gala_title || 'Plexus Gala Evening';
        const galaStatus = pps.gala_status || '';
        const galaDate = (pps.gala_date || '').replace(/\{venue\}/g, galaVenue);
        // Computed from live gala_settings so the card always shows the start time AND all four
        // keynotes. (The admin gala_desc DB field still holds old single-keynote copy with no time.)
        // Anchor to local noon so date-only strings never roll back a day across timezones.
        const galaWhen = galaSettings.date ? fmtD(String(galaSettings.date).slice(0, 10) + 'T12:00:00') : '5 December 2026';
        const galaDesc = `${galaWhen}${galaSettings.time ? ' · ' + galaSettings.time : ''} · ${galaVenue} · Black-tie evening with four keynote speakers from leading universities and hospitals (listed below), a fireside panel, and live music. Limited places.`;
        // Admin-configurable mandatory fields (plexus_page_settings.req_*). 'required' => the
        // browser enforces it (the form is a real <form onsubmit>) AND the server re-checks it.
        const reqStar = (k) => (pps['req_' + k] === 'required') ? ' <span style="color:#c9a962;">*</span>' : '';
        const reqAttr = (k) => (pps['req_' + k] === 'required') ? ' required' : '';
        // Status pill (below the title) + optional date line for a card.
        const evtHead = (status, date) =>
            (status ? `<span class="event-status">${escapeHtml(status)}</span>` : '') +
            (date ? `<div class="event-date">${escapeHtml(date)}</div>` : '');

        const cardConference = `<div class="event-option evt-conference" data-key="conference" data-price="0" onclick="plexToggle(this)">
            <div class="event-checkbox"><i class="fas fa-check"></i></div>
            <div class="event-body"><div class="event-title-row"><span class="event-name">${escapeHtml(confTitle)}</span><span class="event-price free">FREE</span></div>
            ${evtHead(confStatus, confDate)}
            <div class="event-meta">${formatRichText(confDesc)}</div></div></div>`;
        const cardBridges = `<div class="event-option evt-bridges" data-key="bridges" data-price="0" onclick="plexToggle(this)">
            <div class="event-checkbox"><i class="fas fa-check"></i></div>
            <div class="event-body"><div class="event-title-row"><span class="event-name">${escapeHtml(bridgesTitle)}</span><span class="event-price free">FREE</span></div>
            ${evtHead(bridgesStatus, bridgesDate)}
            <div class="event-meta">${formatRichText(bridgesDesc)}</div></div></div>`;
        const cardGala = `<div class="event-option evt-gala" data-key="gala" data-price="${galaPrice}" onclick="plexToggle(this)">
            <div class="event-checkbox"><i class="fas fa-check"></i></div>
            <div class="event-body"><div class="event-title-row"><span class="event-name">${escapeHtml(galaTitle)}</span><span class="event-price">${galaPriceLabel}</span></div>
            ${evtHead(galaStatus, galaDate)}
            <div class="event-meta">${formatRichText(galaDesc)}</div></div></div>`;
        const cards = [
            offered.includes('conference') ? cardConference : '',
            offered.includes('bridges') ? cardBridges : '',
            offered.includes('gala') ? cardGala : ''
        ].join('');
        // Add-to-calendar (.ics) links — only for the events actually offered on this page.
        const calItem = (href, label) => `<a href="${href}" download class="plex-cal-btn"><i class="fas fa-calendar-plus"></i> ${label}</a>`;
        const calLinks = [
            offered.includes('conference') ? calItem('/calendar/plexus.ics', 'Conference') : '',
            offered.includes('gala') ? calItem('/calendar/gala.ics', 'Gala Evening') : '',
            offered.includes('bridges') ? calItem('/calendar/building-bridges.ics', 'Bridges') : ''
        ].join('');

        // Gala keynote highlight — shown when the Gala is offered. Four confirmed keynotes
        // + live music (see galaKeynoteBlock); supersedes the single gala_settings keynote.
        const keynoteCard = offered.includes('gala') ? galaKeynoteBlock() : '';

        // One-click prefill from the Forum wing (/plexus?fn=..&ln=..&email=..&inst=..&src=forum).
        // These are REFLECTED query values echoed into value="" attributes — escape rigorously (XSS).
        const pfPrefill = (k) => escapeHtml((req.query[k] == null ? '' : String(req.query[k])).slice(0, 200));
        const prefFirst = pfPrefill('fn');
        const prefLast  = pfPrefill('ln');
        const prefEmail = pfPrefill('email');
        const prefInst  = pfPrefill('inst');

        const inner = `<div id="plexMain">
            <div class="hero">
                <span class="badge">Plexus 2026 &middot; Zagreb${linkLabel ? ' &middot; ' + escapeHtml(linkLabel) : ''}</span>
                <h1>Reserve your place</h1>
                <p class="lede">${formatRichText(pageLede)}</p>
            </div>
            <div class="plex-layout">
                <div class="card events-col">
                    <div class="section-label" style="margin-top:0;">Choose your events</div>
                    ${cards}
                    ${keynoteCard}
                    <div class="total-display" id="plexTotal"><span class="label">Total</span><span class="amount" id="plexTotalAmt">&euro;0</span></div>
                    ${calLinks ? `<div class="plex-cal-row"><span class="plex-cal-label">Add to your calendar</span><div class="plex-cal-links">${calLinks}</div></div>` : ''}
                </div>
                <div class="card form-col">
                    <form id="plexForm" onsubmit="return plexSubmit(event)">
                        <div class="section-label" style="margin-top:0;">Your details</div>
                        <!-- Account linking: filled by the inline script when a portal login exists on this device (omitted when the member-card toggle for this page is OFF) -->
                        ${showMemberCard ? `<div id="plexLinkNote" style="display:none;margin-bottom:14px;padding:11px 14px;border:1px solid rgba(34,197,94,.35);border-radius:10px;background:rgba(34,197,94,.07);font-size:12.5px;color:#a7f3d0;line-height:1.5;"></div>` : ''}
                        <div class="form-grid">
                            <div class="form-row">
                                <div><label>First name *</label><input id="pf_first" required maxlength="100" value="${prefFirst}"></div>
                                <div><label>Last name *</label><input id="pf_last" required maxlength="100" value="${prefLast}"></div>
                            </div>
                            <div><label>Email *</label><input id="pf_email" type="email" required maxlength="160" value="${prefEmail}"></div>
                            <div class="form-row">
                                <div><label>Institution / Company${reqStar('institution')}</label><input id="pf_inst" maxlength="160"${reqAttr('institution')} value="${prefInst}"></div>
                                <div><label>Country${reqStar('country')}</label><input id="pf_country" maxlength="80"${reqAttr('country')}></div>
                            </div>
                            <div><label>Dietary requirements (for the Gala)</label><input id="pf_diet" maxlength="200" placeholder="e.g. vegetarian"></div>
                            <div><label>Allergies (for the Gala)</label><input id="pf_allergies" maxlength="200" placeholder="e.g. nuts, shellfish"></div>
                            <div><label>Additional guests for the Gala <span style="color:#64748b;font-weight:400;">(max 2)</span></label>
                                <select id="pf_guests" onchange="plexRecompute()">
                                    <option value="0">No additional guests</option>
                                    <option value="1">+1 guest (+&euro;${galaPrice})</option>
                                    <option value="2">+2 guests (+&euro;${galaPrice * 2})</option>
                                </select></div>
                            <div><label>Discount code <span style="color:#64748b;font-weight:400;">(optional, applies to the Gala)</span></label>
                                <div style="display:flex;gap:8px;">
                                    <input id="pf_coupon" maxlength="40" placeholder="Enter code" style="text-transform:uppercase;flex:1;" oninput="plexClearCoupon()">
                                    <button type="button" id="pf_couponBtn" onclick="plexApplyCoupon()" style="padding:11px 16px;border:none;border-radius:9px;background:linear-gradient(135deg,#c9a962,#b8965a);color:#0f172a;font-weight:700;cursor:pointer;white-space:nowrap;">Apply</button>
                                </div>
                                <div id="pf_couponMsg" style="margin-top:6px;font-size:12px;display:none;"></div></div>
                            <div><label>Anything else?${reqStar('notes')}</label><textarea id="pf_notes" maxlength="500"${reqAttr('notes')}></textarea></div>
                        </div>
                        <div class="total-display show" style="margin-top:14px;"><span class="label">To pay now</span><span class="amount" id="plexPayAmt">&euro;0</span></div>
                        <button type="submit" class="submit-btn" id="plexBtn">Complete registration</button>
                        <div class="msg" id="plexMsg"></div>
                        <div id="plexFallback" style="display:none;"></div>
                    </form>
                </div>
            </div>
        </div>`;

        const clientJs = `<script>
        var PLEX_TOKEN = ${JSON.stringify(token || '')};
        var plexDiscount = 0, plexDiscountType = '';
        function plexEsc(s){ return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){ return { '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]; }); }
        // Account linking: this page is served from the portal origin, so a member logged in to
        // the portal on this device is recognised via localStorage. Their registration links to
        // their account (Authorization header -> optionalAuth) and the form prefills — fields
        // stay editable, and the anonymous flow is completely unchanged when no login exists.
        var PLEX_AUTH = null;
        var PLEX_SHOW_CARD = ${JSON.stringify(showMemberCard)};
        try {
            PLEX_AUTH = localStorage.getItem('medx_user_token');
            var plexU = JSON.parse(localStorage.getItem('medx_user_data') || 'null');
            if (PLEX_AUTH && plexU) {
                // The visible card + prefill respect the per-page toggle; PLEX_AUTH survives
                // either way so a signed-in submit still links the registration to the account.
                if (PLEX_SHOW_CARD) {
                    var plexName = ((plexU.first_name || '') + ' ' + (plexU.last_name || '')).trim() || plexU.email || '';
                    var plexNote = document.getElementById('plexLinkNote');
                    if (plexNote) { plexNote.style.display = 'block'; plexNote.innerHTML = 'You are signed in as <strong>' + plexEsc(plexName) + '</strong> \\u2014 this registration will be linked to your Med&amp;X account.'; }
                    var pxF = document.getElementById('pf_first'), pxL = document.getElementById('pf_last'), pxE = document.getElementById('pf_email'), pxI = document.getElementById('pf_inst');
                    if (pxF && !pxF.value) pxF.value = plexU.first_name || '';
                    if (pxL && !pxL.value) pxL.value = plexU.last_name || '';
                    if (pxE && !pxE.value) pxE.value = plexU.email || '';
                    if (pxI && !pxI.value && plexU.institution) pxI.value = plexU.institution;
                }
            } else { PLEX_AUTH = null; }
        } catch (e) { PLEX_AUTH = null; }
        function plexRecompute(){
            var total = 0, galaUnit = 0, galaSel = false;
            document.querySelectorAll('.event-option.selected').forEach(function(o){
                if (o.dataset.key === 'gala') { galaSel = true; galaUnit = Number(o.dataset.price) || 0; }
                else { total += Number(o.dataset.price) || 0; }
            });
            var guests = parseInt((document.getElementById('pf_guests') || {}).value || '0') || 0;
            if (galaSel) {
                var galaSub = galaUnit * (1 + guests);
                if (plexDiscount > 0) {
                    var disc = plexDiscountType === 'fixed' ? plexDiscount : Math.round(galaSub * plexDiscount / 100 * 100) / 100;
                    galaSub = Math.max(0, galaSub - disc);
                }
                total += Math.round(galaSub * 100) / 100;
            }
            var any = document.querySelectorAll('.event-option.selected').length > 0;
            document.getElementById('plexTotal').classList.toggle('show', any);
            document.getElementById('plexTotalAmt').textContent = '\\u20AC' + total;
            document.getElementById('plexPayAmt').textContent = '\\u20AC' + total;
            document.getElementById('plexBtn').textContent = total > 0 ? ('Proceed to payment \\u2014 \\u20AC' + total) : 'Complete registration';
        }
        function plexClearCoupon(){ plexDiscount = 0; plexDiscountType = ''; var m = document.getElementById('pf_couponMsg'); if (m) m.style.display = 'none'; plexRecompute(); }
        async function plexApplyCoupon(){
            var code = ((document.getElementById('pf_coupon') || {}).value || '').trim();
            var m = document.getElementById('pf_couponMsg');
            if (!code) { if (m) { m.style.display = 'block'; m.style.color = '#fca5a5'; m.textContent = 'Enter a code'; } return; }
            var b = document.getElementById('pf_couponBtn'); b.disabled = true; b.textContent = '\\u2026';
            try {
                var r = await fetch('/api/invite/validate-coupon', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ code: code, event_type: 'gala' }) });
                var d = await r.json();
                if (d.valid) { plexDiscount = Number(d.discount_value) || 0; plexDiscountType = d.discount_type; if (m) { m.style.display = 'block'; m.style.color = '#5eead4'; m.textContent = (d.discount_type === 'fixed' ? ('\\u20AC' + d.discount_value + ' off') : (d.discount_value + '% off')) + ' applied to the Gala'; } }
                else { plexDiscount = 0; plexDiscountType = ''; if (m) { m.style.display = 'block'; m.style.color = '#fca5a5'; m.textContent = d.error || 'Invalid or expired code'; } }
            } catch(e) { if (m) { m.style.display = 'block'; m.style.color = '#fca5a5'; m.textContent = 'Could not validate'; } }
            b.disabled = false; b.textContent = 'Apply';
            plexRecompute();
        }
        function plexToggle(el){ el.classList.toggle('selected'); plexRecompute(); }
        function plexErr(m){ var e=document.getElementById('plexMsg'); e.className='msg err'; e.textContent=m; }
        async function plexSubmit(ev){
            ev.preventDefault();
            var sel = { conference:0, bridges:0, gala:0 };
            document.querySelectorAll('.event-option.selected').forEach(function(o){ sel[o.dataset.key] = 1; });
            if(!sel.conference && !sel.bridges && !sel.gala){ plexErr('Please select at least one event.'); return false; }
            var btn = document.getElementById('plexBtn'); btn.disabled = true; btn.textContent = 'Processing\\u2026';
            var body = {
                source: 'plexus',
                link_token: PLEX_TOKEN || undefined,
                first_name: document.getElementById('pf_first').value.trim(),
                last_name: document.getElementById('pf_last').value.trim(),
                email: document.getElementById('pf_email').value.trim(),
                institution: document.getElementById('pf_inst').value.trim(),
                country: document.getElementById('pf_country').value.trim(),
                dietary: document.getElementById('pf_diet').value.trim(),
                allergies: (document.getElementById('pf_allergies') || {}).value ? document.getElementById('pf_allergies').value.trim() : '',
                guest_count: parseInt((document.getElementById('pf_guests') || {}).value || '0') || 0,
                coupon: ((document.getElementById('pf_coupon') || {}).value || '').trim(),
                notes: document.getElementById('pf_notes').value.trim(),
                selected_conference: sel.conference, selected_bridges: sel.bridges, selected_gala: sel.gala
            };
            try {
                var plexHeaders = { 'Content-Type': 'application/json' };
                if (PLEX_AUTH) plexHeaders['Authorization'] = 'Bearer ' + PLEX_AUTH; // account linking (optionalAuth)
                var r = await fetch('/api/croatians-abroad/register', { method:'POST', headers: plexHeaders, body: JSON.stringify(body) });
                var d = await r.json();
                if(!r.ok){
                    if(r.status >= 500){ plexPayFallback(); } else { plexErr(d.error || 'Registration failed. Please try again.'); }
                    btn.disabled=false; plexRecompute(); return false;
                }
                if(d.checkout_url){ window.location = d.checkout_url; return false; }
                document.getElementById('plexMain').innerHTML = '<div class="card" style="text-align:center;max-width:640px;margin:0 auto;padding:36px 28px;"><div style="font-size:46px;color:#22c55e;margin-bottom:10px;"><i class="fas fa-circle-check"></i></div><h1>You are registered</h1><p class="lede" style="margin-top:10px;">Thank you, ' + plexEsc(body.first_name) + '. A confirmation email with your check-in QR code is on its way to ' + plexEsc(body.email) + '. We look forward to welcoming you to Plexus 2026 in Zagreb.</p></div>';
            } catch(e){ plexPayFallback(); btn.disabled=false; plexRecompute(); }
            return false;
        }
        function plexPayFallback(){
            var box = document.getElementById('plexFallback');
            if(!box) return;
            var m = document.getElementById('plexMsg'); if(m) m.style.display='none';
            box.style.display='block';
            box.innerHTML =
                '<div style="margin-top:14px;padding:20px 18px;border:1px solid rgba(201,169,98,0.4);border-radius:14px;background:rgba(201,169,98,0.06);text-align:left;">'
                + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;"><i class="fas fa-shield-halved" style="color:#c9a962;"></i><strong style="color:#e8e2d4;font-size:14px;">We could not open secure checkout</strong></div>'
                + '<p style="font-size:13px;color:#94a3b8;line-height:1.6;margin:0 0 14px;">Your details are safe and nothing has been charged. This is usually a brief connection issue. Try again, or reach us and we will send you a secure payment link.</p>'
                + '<div style="display:flex;flex-wrap:wrap;gap:8px;">'
                + '<button type="button" onclick="plexRetry()" style="display:inline-flex;align-items:center;gap:6px;padding:10px 16px;border:none;border-radius:9px;background:linear-gradient(135deg,#c9a962,#b8965a);color:#0f172a;font-weight:700;cursor:pointer;font-size:13px;"><i class="fas fa-rotate-right"></i> Try again</button>'
                + '<a href="mailto:laura.rodman@medx.hr?subject=Plexus%202026%20registration%20%E2%80%94%20payment%20help" style="display:inline-flex;align-items:center;gap:6px;padding:10px 16px;border:1px solid rgba(201,169,98,0.5);border-radius:9px;color:#e8e2d4;font-weight:600;text-decoration:none;font-size:13px;"><i class="fas fa-envelope"></i> laura.rodman@medx.hr</a>'
                + '</div></div>';
        }
        function plexRetry(){
            var box = document.getElementById('plexFallback'); if(box){ box.style.display='none'; box.innerHTML=''; }
            var form = document.getElementById('plexForm');
            if(form && typeof form.requestSubmit === 'function'){ form.requestSubmit(); }
            else { plexSubmit(new Event('submit')); }
        }
        </script>`;

        return res.send(PLEXUS_SHELL(inner + clientJs, 'Plexus 2026 — Reserve Your Place'));
    } catch (err) {
        console.error('[Plexus page] error:', err.message);
        return res.status(500).send(plexusNoticePage('Something went wrong', 'Please try again, or contact laura.rodman@medx.hr.'));
    }
});

// ========== PLEXUS WEEK 2026 — PUBLIC INVITATION PAGES (Building Bridges / Donor Night) ==========
// Two free, invitation-only events. Server-rendered like /plexus above (must sit BEFORE
// express.static so they take priority over the SPA). Both pages share one premium shell in the
// PLEXUS_SHELL design language; the slug picks the accent, copy and form fields. The form posts
// to /api/public-events/register, which resolves the seeded bridges_events row by exact NAME
// server-side — the client never supplies an event identity.
const PUBLIC_EVENT_PAGES = {
    'building-bridges': {
        accent: '#2dd4bf',
        pageTitle: 'Building Bridges in Biomedicine Croatia — Plexus Week 2026',
        heading: 'Building Bridges in Biomedicine Croatia',
        framing: 'The fifth edition of Building Bridges in Biomedicine (after Washington, New York, London and Zürich) brings Croatia’s biomedical diaspora and the world’s leading institutions to the same table. Panel conversations on international collaboration give way to open networking, and the first steps of new collaborations begin.',
        facts: ['4 or 5 December 2026', 'Zagreb', 'By invitation'],
        note: 'The exact date, time and venue follow with your invitation.',
        dietary: false,
        submitLabel: 'Confirm your participation',
        successHeading: 'Your participation is confirmed'
    },
    'donor-night': {
        accent: '#c9a962',
        pageTitle: 'Plexus Donor Night — Plexus Week 2026',
        heading: 'Plexus Donor Night',
        framing: 'An evening of giving for the future of Croatian biomedicine. An invitation-only supper with the leadership of Cambridge, Massachusetts General Hospital, University Health Network Toronto, UCLA Health and Mass General Brigham. What gathers around this table advances the Plexus Fellowship, the Accelerator, the Plexus Conference and Building Bridges in Biomedicine.',
        facts: ['Friday 4 December 2026', '19:30–22:30', 'Esplanade Zagreb, private salon', 'Invitation only'],
        note: '',
        dietary: true,
        submitLabel: 'Confirm your seat',
        successHeading: 'Your seat is confirmed'
    }
};

function renderPublicEventPage(slug) {
    const cfg = PUBLIC_EVENT_PAGES[slug];
    const factLine = cfg.facts.map(f => `<span>${f}</span>`).join('<span class="dot">&middot;</span>');
    // "Vec imate racun?" member-card toggle for this fixed page (admin -> Sign-up Forms ->
    // fixed-page toggles; rewards_settings key member_card_page-<slug>, absent = ON). OFF hides
    // the signed-in note + prefill only — the Authorization header on submit (account linking)
    // and the anonymous flow are unchanged in both states.
    const showMemberCard = rewardsSetting('member_card_page-' + slug, '1') !== '0';
    return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>${cfg.pageTitle}</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap" rel="stylesheet"><style>
    * { margin:0; padding:0; box-sizing:border-box; }
    body { min-height:100vh; background:linear-gradient(160deg,#0f172a,#1e293b); font-family:'Inter',-apple-system,BlinkMacSystemFont,system-ui,sans-serif; color:#e2e8f0; padding:48px 20px 40px; }
    .container { max-width:1020px; margin:0 auto; }
    .logo { text-align:center; margin-bottom:34px; }
    .logo img { height:36px; width:auto; display:inline-block; filter:brightness(0) invert(1); opacity:0.92; }
    .hero { position:relative; text-align:center; padding:58px 40px 54px; margin-bottom:26px; }
    .hero::before, .hero::after { content:''; position:absolute; width:46px; height:46px; }
    .hero::before { top:0; left:0; border-top:1px solid rgba(201,169,98,0.6); border-left:1px solid rgba(201,169,98,0.6); }
    .hero::after { bottom:0; right:0; border-bottom:1px solid rgba(201,169,98,0.6); border-right:1px solid rgba(201,169,98,0.6); }
    .eyebrow { font-size:11px; font-weight:600; letter-spacing:4px; text-transform:uppercase; color:${cfg.accent}; margin-bottom:22px; }
    h1 { font-family:'Cormorant Garamond',Georgia,serif; font-weight:600; font-size:clamp(34px,5.5vw,52px); line-height:1.12; color:#fff; margin-bottom:20px; }
    .framing { max-width:640px; margin:0 auto 26px; font-size:15.5px; line-height:1.75; color:#94a3b8; }
    .facts { display:flex; flex-wrap:wrap; justify-content:center; gap:6px 12px; font-size:13.5px; font-weight:500; color:#e2e8f0; letter-spacing:0.3px; }
    .facts .dot { color:${cfg.accent}; }
    .note { margin-top:14px; font-family:'Cormorant Garamond',Georgia,serif; font-style:italic; font-size:16.5px; color:#c9a962; }
    .cal-add { margin-top:22px; }
    .cal-add-btn { display:inline-flex; align-items:center; gap:8px; padding:11px 20px; border:1px solid ${cfg.accent}; border-radius:999px; background:${cfg.accent}14; color:#e2e8f0; font-size:13px; font-weight:600; letter-spacing:0.3px; text-decoration:none; transition:all 0.2s; }
    .cal-add-btn:hover { background:${cfg.accent}26; transform:translateY(-1px); }
    .cal-add-btn svg { color:${cfg.accent}; }
    .form-wrap { max-width:520px; margin:0 auto; }
    .card { background:rgba(255,255,255,0.03); border:1px solid rgba(201,169,98,0.22); border-radius:20px; padding:38px 36px; }
    .section-label { font-size:11px; font-weight:600; letter-spacing:2.5px; text-transform:uppercase; color:${cfg.accent}; margin-bottom:22px; text-align:center; }
    .form-grid { display:grid; gap:16px; }
    .form-row { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
    label { display:block; font-size:11px; font-weight:600; letter-spacing:1px; text-transform:uppercase; color:#94a3b8; margin-bottom:6px; }
    input { width:100%; padding:12px 14px; border:1px solid rgba(255,255,255,0.1); border-radius:10px; background:rgba(255,255,255,0.05); color:#fff; font-size:14px; font-family:inherit; }
    input:focus { border-color:${cfg.accent}; outline:none; box-shadow:0 0 0 3px ${cfg.accent}1f; }
    input::placeholder { color:#64748b; }
    .submit-btn { width:100%; margin-top:22px; padding:16px; border:none; border-radius:11px; background:linear-gradient(135deg,#c9a962,#b8965a); color:#0f172a; font-size:15px; font-weight:600; letter-spacing:0.4px; cursor:pointer; font-family:inherit; transition:all 0.2s; }
    .submit-btn:hover { transform:translateY(-1px); box-shadow:0 8px 22px rgba(201,169,98,0.25); }
    .submit-btn:disabled { opacity:0.55; cursor:not-allowed; transform:none; box-shadow:none; }
    .msg { margin-top:14px; padding:12px 14px; border-radius:9px; font-size:13px; display:none; }
    .msg.err { display:block; background:rgba(239,68,68,0.12); border:1px solid rgba(239,68,68,0.3); color:#fca5a5; }
    .confirm-heading { font-family:'Cormorant Garamond',Georgia,serif; font-weight:600; font-size:30px; color:#fff; text-align:center; margin-bottom:8px; }
    .qr-tile { background:#fff; border-radius:16px; padding:18px; width:fit-content; margin:24px auto 14px; box-shadow:0 6px 24px rgba(0,0,0,0.35); }
    .qr-tile img { display:block; width:200px; height:200px; }
    .manual-code { text-align:center; font-family:'Courier New',monospace; font-size:14px; letter-spacing:3px; color:#e2e8f0; }
    .manual-code .mc-label { font-family:'Inter',sans-serif; font-size:9px; letter-spacing:1.5px; color:#94a3b8; margin-right:8px; }
    .confirm-line { max-width:400px; margin:18px auto 0; text-align:center; font-size:13.5px; line-height:1.7; color:#94a3b8; }
    .foot { text-align:center; font-size:12px; color:#64748b; margin-top:32px; }
    .foot a { color:#c9a962; text-decoration:none; }
    @media (max-width: 640px) {
        body { padding:30px 14px; }
        .hero { padding:44px 18px 40px; }
        .card { padding:28px 20px; }
        .form-row { grid-template-columns:1fr; gap:16px; }
        input { font-size:16px; } /* <16px makes iOS Safari zoom the page on focus */
    }
</style></head><body><div class="container">
    <div class="logo"><img src="${MEDX_LOGO_URL}" alt="Med&amp;X" /></div>
    <div class="hero">
        <div class="eyebrow">Plexus Week 2026 &middot; Zagreb</div>
        <h1>${cfg.heading}</h1>
        <p class="framing">${cfg.framing}</p>
        <div class="facts">${factLine}</div>
        ${cfg.note ? `<div class="note">${cfg.note}</div>` : ''}
        <div class="cal-add"><a href="/calendar/${slug}.ics" download class="cal-add-btn"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg> Add to calendar</a></div>
    </div>
    <div class="form-wrap">
        <div class="card" id="peCard">
            <form id="peForm" onsubmit="return peSubmit(event)">
                <div class="section-label">Your details</div>
                <!-- Account linking: filled by the inline script when a portal login exists on this device (omitted when the member-card toggle for this page is OFF) -->
                ${showMemberCard ? `<div id="peLinkNote" style="display:none;margin-bottom:14px;padding:11px 14px;border:1px solid rgba(34,197,94,.35);border-radius:10px;background:rgba(34,197,94,.07);font-size:12.5px;color:#a7f3d0;line-height:1.5;"></div>` : ''}
                <div class="form-grid">
                    <div class="form-row">
                        <div><label for="pe_first">First name</label><input id="pe_first" name="first_name" autocomplete="given-name" required maxlength="100"></div>
                        <div><label for="pe_last">Last name</label><input id="pe_last" name="last_name" autocomplete="family-name" required maxlength="100"></div>
                    </div>
                    <div><label for="pe_email">Email</label><input id="pe_email" name="email" type="email" autocomplete="email" inputmode="email" required maxlength="160"></div>
                    <div><label for="pe_inst">Institution</label><input id="pe_inst" name="organization" autocomplete="organization" required maxlength="160"></div>
                    <div><label for="pe_role">Role / Title</label><input id="pe_role" name="organization_title" autocomplete="organization-title" required maxlength="120"></div>
                    ${cfg.dietary ? `<div><label for="pe_diet">Dietary requirements <span style="text-transform:none;letter-spacing:0;color:#64748b;font-weight:400;">(optional)</span></label><input id="pe_diet" name="dietary" autocomplete="off" maxlength="200"></div>` : ''}
                </div>
                <button type="submit" class="submit-btn" id="peBtn">${cfg.submitLabel}</button>
                <div class="msg" id="peMsg"></div>
            </form>
        </div>
    </div>
    <div class="foot">Questions? <a href="mailto:laura.rodman@medx.hr">laura.rodman@medx.hr</a> &middot; <a href="https://medx.hr">medx.hr</a></div>
</div>
<script>
    var PE_SLUG = ${JSON.stringify(slug)};
    function peEsc(s){ return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){ return { '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]; }); }
    function peErr(m){ var e = document.getElementById('peMsg'); e.className = 'msg err'; e.textContent = m; }
    // Account linking: this page is served from the portal origin, so a member logged in to
    // the portal on this device is recognised via localStorage. Their registration links to
    // their account (Authorization header -> optionalAuth) and the form prefills — fields
    // stay editable, and the anonymous flow is completely unchanged when no login exists.
    var PE_TOKEN = null;
    var PE_SHOW_CARD = ${JSON.stringify(showMemberCard)};
    try {
        PE_TOKEN = localStorage.getItem('medx_user_token');
        var peU = JSON.parse(localStorage.getItem('medx_user_data') || 'null');
        if (PE_TOKEN && peU) {
            // The visible card + prefill respect the per-page toggle; PE_TOKEN survives either
            // way so a signed-in submit still links the registration to the account.
            if (PE_SHOW_CARD) {
                var peName = ((peU.first_name || '') + ' ' + (peU.last_name || '')).trim() || peU.email || '';
                var peNote = document.getElementById('peLinkNote');
                if (peNote) { peNote.style.display = 'block'; peNote.innerHTML = 'You are signed in as <strong>' + peEsc(peName) + '</strong> \\u2014 this registration will be linked to your Med&amp;X account.'; }
                var peF = document.getElementById('pe_first'), peL = document.getElementById('pe_last'), peE = document.getElementById('pe_email'), peI = document.getElementById('pe_inst');
                if (peF && !peF.value) peF.value = peU.first_name || '';
                if (peL && !peL.value) peL.value = peU.last_name || '';
                if (peE && !peE.value) peE.value = peU.email || '';
                if (peI && !peI.value && peU.institution) peI.value = peU.institution;
            }
        } else { PE_TOKEN = null; }
    } catch (e) { PE_TOKEN = null; }
    async function peSubmit(ev){
        ev.preventDefault();
        var btn = document.getElementById('peBtn'); btn.disabled = true; btn.textContent = 'One moment\\u2026';
        var diet = document.getElementById('pe_diet');
        var body = {
            event: PE_SLUG,
            first_name: document.getElementById('pe_first').value.trim(),
            last_name: document.getElementById('pe_last').value.trim(),
            email: document.getElementById('pe_email').value.trim(),
            institution: document.getElementById('pe_inst').value.trim(),
            role: document.getElementById('pe_role').value.trim(),
            dietary: diet ? diet.value.trim() : ''
        };
        try {
            var peHeaders = { 'Content-Type': 'application/json' };
            if (PE_TOKEN) peHeaders['Authorization'] = 'Bearer ' + PE_TOKEN; // account linking (optionalAuth)
            var r = await fetch('/api/public-events/register', { method:'POST', headers: peHeaders, body: JSON.stringify(body) });
            var d = await r.json();
            if (!r.ok) { peErr(d.error || 'Something went wrong. Please try again.'); btn.disabled = false; btn.textContent = ${JSON.stringify(cfg.submitLabel)}; return false; }
            document.getElementById('peCard').innerHTML =
                '<div class="confirm-heading">${cfg.successHeading}</div>' +
                (d.qrDataUrl ? '<div class="qr-tile"><img src="' + peEsc(d.qrDataUrl) + '" alt="Your entry QR"></div>' : '') +
                (d.manualCode ? '<div class="manual-code"><span class="mc-label">MANUAL CODE</span>' + peEsc(d.manualCode) + '</div>' : '') +
                '<p class="confirm-line">' + (d.resent
                    ? peEsc(d.message || ('You are already confirmed. Your entry QR has been re-sent to ' + body.email + '.'))
                    : 'A confirmation email with your entry QR is on its way to ' + peEsc(body.email) + '. Present it at arrival.') + '</p>';
        } catch(e) { peErr('Network error. Please try again.'); btn.disabled = false; btn.textContent = ${JSON.stringify(cfg.submitLabel)}; }
        return false;
    }
</script></body></html>`;
}

