        if (status) { sql += ' AND a.status = ?'; params.push(status); }
        if (program_id) { sql += ' AND a.program_id = ?'; params.push(program_id); }

        sql += ' ORDER BY a.submitted_at DESC, a.created_at DESC';

        const applications = query.all(sql, params);
