            db.run(`INSERT OR REPLACE INTO push_subscriptions (id, user_id, endpoint, p256dh, auth) VALUES (?, ?, ?, ?, ?)`,
                [id, req.user.id, endpoint, keys.p256dh, keys.auth]);
